 {enemyPoints.slice(0,count).map((point:number[],i:number)=>{const dest=[mix(point[0],redFrom[0],.48),mix(point[1],redFrom[1],.48)];return <Marchers key={i} p={{...p,seed:p.seed+':'+i}} cam={cam} points={[point,dest]} progress={march*.55} color={BLUE} enemy amount={14} night={mood==='night'}/>;})}
