// 地名仍锚定同一真实地理点，文字在屏幕平面绘制，近景不随山坡扭曲或放大。
function TerrainLabels({p,labels,cam}:any){return <Svg>{labels.map((l:any,i:number)=>{const a=GEO.places[l.key],v=ground(l.point??[a.lon,a.lat]).project(cam),x=(v.x+1)*W/2,y=(1-v.y)*H/2;if(v.z<0||v.z>1||x<55||x>W-55||y<160||y>785)return null;const end=x>980,tx=Math.min(1240,Math.max(140,x+(end?-24:24))),ty=clamp(y-20,190,755);return <g key={i}><circle cx={x} cy={y} r={4} fill={GOLD}/><path d={`M${x} ${y} L${tx} ${ty+6}`} stroke={GOLD} strokeWidth={1.5}/><text x={tx} y={ty} textAnchor={end?'end':'start'} fontFamily={p.fonts.text} fontSize={29} fontWeight={650} fill={p.theme.text} stroke={p.theme.background} strokeWidth={7} paintOrder="stroke" strokeLinejoin="round">{l.label}</text></g>;})}</Svg>;}

