function ParallaxMesh({image,depth}:any){const texture=useLoader(THREE.TextureLoader,String(image));texture.colorSpace=THREE.SRGBColorSpace;const geometry=useMemo(()=>{const g=new THREE.PlaneGeometry(10.85,6.104,200,112),a=g.attributes.position;for(let i=0;i<a.count;i++){if(i%4096===0)pulse();a.setZ(i,sample(depth,(i%201)/200,Math.floor(i/201)/112)*.22);}g.computeVertexNormals();return g;},[depth]);useEffect(()=>()=>geometry.dispose(),[geometry]);return <mesh geometry={geometry}><meshBasicMaterial map={texture}/></mesh>;}
